#newsroom .newsroom-4cut-archive{margin:0 0 12px;padding:0 12px;border:1px solid var(--border-strong);border-radius:12px;background:var(--surface-raised)}
#newsroom .newsroom-4cut-archive summary{font-weight:700}
#newsroom .newsroom-4cut .newsroom-4cut-past{display:flex;flex-wrap:wrap;gap:8px;list-style:none;padding:0;margin:0 0 12px}
#newsroom .newsroom-4cut .newsroom-4cut-past li{min-width:0;max-width:100%;padding:0}
#newsroom .newsroom-4cut button[aria-pressed="true"]{background:var(--surface-panel);outline:2px solid var(--text-primary);outline-offset:2px}
