#app #newsroom .company-followup-channels b{font-size:14px;word-break:keep-all;overflow-wrap:break-word}
#app #newsroom .company-followup-channels em{font-size:11px;word-break:keep-all;overflow-wrap:break-word}
#app #newsroom .company-followup-channels :is(.followup-channel-symbol,.followup-company-mark){width:32px;height:32px}
